const b = $input.first().json.body || $input.first().json;

// Determinar cuántas piezas según paquete
const config = {
  'Starter':  { reels: 0, posts: 8,  stories: 4,  ugc: 0 },
  'Pro':      { reels: 4, posts: 16, stories: 8,  ugc: 1 },
  'Premium':  { reels: 8, posts: 20, stories: 15, ugc: 3 },
};
const plan = config[b.paquete] || config['Starter'];

// Generar prompt para Higgsfield según tipo
const tipo = b.tipo_contenido || 'Reel';
const promptBase = [
  'Crea un video de ' + tipo + ' para ' + b.negocio + ', un negocio de ' + (b.categoria || 'servicios') + ' en Miami.',
  'Estilo: ' + (b.estilo || 'moderno, vibrante, auténtico'),
  'Descripción: ' + (b.descripcion || 'Muestra el negocio en acción'),
  'Plataforma: ' + (b.plataforma || 'Instagram'),
  'Duración: ' + (tipo === 'Reel' ? '15-30 segundos' : '10-15 segundos'),
  'Idioma: bilingüe español/inglés en los textos superpuestos',
].join('. ');

return [{ json: {
  ...b,
  plan,
  promptHiggsfield: promptBase,
  timestamp: new Date().toISOString(),
}}];

