const claudeResp = $input.first().json;
const promptOptimizado = claudeResp.content && claudeResp.content[0] && claudeResp.content[0].text || '';

// Pasar el prompt optimizado junto con los datos del cliente
const prev = $('Calcular plan de contenido').first().json;

return [{ json: {
  ...prev,
  promptOptimizado,
  // Aquí iría la llamada a Higgsfield API cuando esté disponible
  higgsfieldPayload: {
    prompt: promptOptimizado,
    duration: 15,
    aspect_ratio: prev.plataforma === 'TikTok' ? '9:16' : '9:16',
    style: 'cinematic'
  }
}}];
